const String globalExploreCatalogVersion = 'global_launch_v2';
const int globalExploreLaunchCountryCount = 20;
const int globalExploreLaunchCityCount = 100;

/// Bundled launch catalog supplement.
///
/// Existing rich Istanbul / Tokyo / Rome seed remains in ExploreLocalDataSource.
/// This catalog adds the other launch cities so an incomplete remote database
/// cannot collapse the app back to only three cities.
List<ExploreContentModel> getGlobalExploreCatalog(String languageCode) {
  final locale = _supportedLocale(languageCode);
  return [
    ..._items.map((item) => item.toModel(locale)),
    ..._launchCityExpansionItems.map((item) => item.toModel(locale)),
    ..._fruitItems.map((item) => item.toModel(locale)),
  ];
}

List<_GlobalCatalogItem> get _fruitItems {
  final result = <_GlobalCatalogItem>[];
  const locale = 'en';

  for (final item in <_GlobalCatalogItem>[
    ..._items,
    ..._launchCityExpansionItems,
  ]) {
    if (item.category != ExploreCategory.snack) continue;

    result.add(
      _GlobalCatalogItem(
        id: _fruitId(item.id),
        countryCode: item.countryCode,
        countryDefaultName: item.countryDefaultName,
        cityName: item.cityName,
        category: ExploreCategory.fruit,
        title: _fruitTitle(item.countryCode, locale),
        latitude: item.latitude + 0.00035,
        longitude: item.longitude - 0.00035,
        coverImageUrl:
            'https://images.unsplash.com/photo-1610832958506-aa56368176cf?auto=format&fit=crop&w=1200&q=80',
        isFeatured: false,
      ),
    );
  }

  return result;
}

