String _fruitTitle(String countryCode, String locale) {
  final country = _countryName(countryCode, locale, countryCode);
  return switch (locale) {
    'tr' => '$country mevsim meyveleri',
    'de' => 'Saisonales Obst aus $country',
    'fr' => 'Fruits de saison de $country',
    'es' => 'Fruta de temporada de $country',
    'it' => 'Frutta di stagione di $country',
    'ar' => 'فاكهة موسمية من $country',
    _ => 'Seasonal fruit from $country',
  };
}

String _supportedLocale(String value) {
  const supported = {'en', 'tr', 'de', 'fr', 'es', 'it', 'ar', 'zh', 'ru', 'ko', 'ja', 'pt', 'nl'};
  final normalized = value.trim().toLowerCase();
  return supported.contains(normalized) ? normalized : 'en';
}

class _GlobalCatalogItem {
  const _GlobalCatalogItem({
    required this.id,
    required this.countryCode,
    required this.countryDefaultName,
    required this.cityName,
    required this.category,
    required this.title,
    required this.latitude,
    required this.longitude,
    required this.coverImageUrl,
    required this.isFeatured,
  });

  final String id;
  final String countryCode;
  final String countryDefaultName;
  final String cityName;
  final ExploreCategory category;
  final String title;
  final double latitude;
  final double longitude;
  final String coverImageUrl;
  final bool isFeatured;

  ExploreContentModel toModel(String locale) {
    final copy = _copy(locale, category.value);
    final countryName = _countryName(countryCode, locale, countryDefaultName);
    return ExploreContentModel(
      id: id,
      countryCode: countryCode,
      countryName: countryName,
      cityName: cityName,
      category: category,
      title: title,
      shortDescription: copy.$1
          .replaceAll('{title}', title)
          .replaceAll('{city}', cityName)
          .replaceAll('{country}', countryName),
      description: copy.$2
          .replaceAll('{title}', title)
          .replaceAll('{city}', cityName)
          .replaceAll('{country}', countryName),
      latitude: latitude,
      longitude: longitude,
      coverImageUrl: coverImageUrl,
      tags: [category.value, cityName.toLowerCase(), countryCode.toLowerCase()],
      metadata: _metadata(category, locale),
      galleryImageUrls: const [],
      isFeatured: isFeatured,
    );
  }
}

ExploreMetadata _metadata(ExploreCategory category, String locale) {
  final copy = _localizedMetadata[locale] ?? _localizedMetadata['en']!;
  return switch (category) {
    ExploreCategory.place => ExploreMetadata(
        bestTime: copy['placeBestTime'],
        localTip: copy['placeTip'],
        estimatedVisitMinutes: 90,
        coordinatePrecision: 'city_area',
        editorialStatus: 'needs_exact_pin_review',
      ),
    ExploreCategory.food || ExploreCategory.snack || ExploreCategory.drink =>
      ExploreMetadata(
        priceLevel: 2,
        bestTime: copy['foodBestTime'],
        localTip: copy['foodTip'],
        coordinatePrecision: 'city_area',
        editorialStatus: 'needs_exact_pin_review',
      ),
    ExploreCategory.culture => ExploreMetadata(
        bestTime: copy['cultureBestTime'],
        localTip: copy['cultureTip'],
        estimatedVisitMinutes: 60,
        etiquette: copy['cultureEtiquette'],
        coordinatePrecision: 'city_area',
        editorialStatus: 'needs_exact_pin_review',
      ),
    ExploreCategory.fruit => ExploreMetadata(
        priceLevel: 1,
        bestTime: copy['fruitBestTime'],
        localTip: copy['fruitTip'],
        coordinatePrecision: 'city_area',
        editorialStatus: 'needs_exact_pin_review',
      ),
  };
}

